/// Flat-visitor decoder for Widths: a (location, id) state machine over the
/// corelib's streaming callbacks, with a bounded location stack.
const _Widths__Visitor = struct {
    m: *Widths,
    alloc: std.mem.Allocator,
    stack: [256]_Loc = undefined,
    sp: usize = 0,
    cur: _Loc = .root,
    acc: sofab.PayloadAcc = .{}, // only a payload split across feed chunks lands here
    inv: bool = false, // a scalar array over its schema count, or a wrapper element id >= count -> INVALID
    askip: usize = 0, // elements left to discard from a wire-type-contradictory array

    const _Loc = enum {
        root,
        dead, // skipped subtree: an undeclared sequence id, a S7.3 wire-type mismatch, or a failed per-element allocation
    };

    pub fn unsigned(self: *_Widths__Visitor, id: sofab.Id, value: sofab.Unsigned) void {
        if (self.askip > 0) {
            self.askip -= 1;
            return;
        }
        switch (self.cur) {
            .root => switch (id) {
                12 => {
                    if (value > 255) {
                        self.inv = true;
                        return;
                    }
                    self.m.b8 = @intCast(value);
                },
                13 => {
                    if (value > 65535) {
                        self.inv = true;
                        return;
                    }
                    self.m.b16 = @intCast(value);
                },
                14 => {
                    if (value > 4294967295) {
                        self.inv = true;
                        return;
                    }
                    self.m.b32 = @intCast(value);
                },
                15 => self.m.b64 = value,
                16 => {
                    if (value > 255) {
                        self.inv = true;
                        return;
                    }
                    self.m.nothing = @intCast(value);
                },
                17 => self.m.all_on = value,
                18 => {
                    if (value > 255) {
                        self.inv = true;
                        return;
                    }
                    self.m.in_u8 = @intCast(value);
                },
                19 => {
                    if (value > 65535) {
                        self.inv = true;
                        return;
                    }
                    self.m.in_u16 = @intCast(value);
                },
                20 => {
                    if (value > 4294967295) {
                        self.inv = true;
                        return;
                    }
                    self.m.in_u32 = @intCast(value);
                },
                21 => self.m.in_u64 = value,
                22 => {
                    if (value > 255) {
                        self.inv = true;
                        return;
                    }
                    self.m.in_none = @intCast(value);
                },
                else => {},
            },
            else => {},
        }
    }

    pub fn signed(self: *_Widths__Visitor, id: sofab.Id, value: sofab.Signed) void {
        if (self.askip > 0) {
            self.askip -= 1;
            return;
        }
        switch (self.cur) {
            .root => switch (id) {
                0 => {
                    if (value < -128 or value > 127) {
                        self.inv = true;
                        return;
                    }
                    self.m.tiny = @intCast(value);
                },
                1 => {
                    if (value < -128 or value > 127) {
                        self.inv = true;
                        return;
                    }
                    self.m.tiny_min = @intCast(value);
                },
                2 => {
                    if (value < -128 or value > 127) {
                        self.inv = true;
                        return;
                    }
                    self.m.tiny_max = @intCast(value);
                },
                3 => {
                    if (value < -32768 or value > 32767) {
                        self.inv = true;
                        return;
                    }
                    self.m.short_lo = @intCast(value);
                },
                4 => {
                    if (value < -32768 or value > 32767) {
                        self.inv = true;
                        return;
                    }
                    self.m.short_hi = @intCast(value);
                },
                5 => {
                    if (value < -2147483648 or value > 2147483647) {
                        self.inv = true;
                        return;
                    }
                    self.m.wide_min = @intCast(value);
                },
                6 => {
                    if (value < -2147483648 or value > 2147483647) {
                        self.inv = true;
                        return;
                    }
                    self.m.wide_max = @intCast(value);
                },
                7 => {
                    if (value < -128 or value > 127) {
                        self.inv = true;
                        return;
                    }
                    self.m.level = @intCast(value);
                },
                8 => {
                    if (value < -128 or value > 127) {
                        self.inv = true;
                        return;
                    }
                    self.m.level_hi = @intCast(value);
                },
                9 => {
                    if (value < -128 or value > 127) {
                        self.inv = true;
                        return;
                    }
                    self.m.in_i8 = @intCast(value);
                },
                10 => {
                    if (value < -32768 or value > 32767) {
                        self.inv = true;
                        return;
                    }
                    self.m.in_i16 = @intCast(value);
                },
                11 => {
                    if (value < -2147483648 or value > 2147483647) {
                        self.inv = true;
                        return;
                    }
                    self.m.in_i32 = @intCast(value);
                },
                23 => {
                    if (value < -2147483648 or value > 2147483647) {
                        self.inv = true;
                        return;
                    }
                    self.m.past_i16 = @intCast(value);
                },
                else => {},
            },
            else => {},
        }
    }

    pub fn arrayBegin(self: *_Widths__Visitor, _: sofab.Id, kind: sofab.ArrayKind, count: usize) void {
        self.askip = switch (kind) {
            .unsigned => switch (self.cur) {
                else => count,
            },
            .signed => switch (self.cur) {
                else => count,
            },
            .fp32 => 0,
            .fp64 => 0,
        };
    }

    /// Give a string/blob arm ONE contiguous payload, whatever the feed
    /// chunking was. Returns null while the payload is still incomplete.
    ///
    /// `borrow` is always false: NEITHER path hands a chunk window to a
    /// destination. Streaming cannot -- a payload completing inside the
    /// corelib's fixed, REUSED carry buffer is indistinguishable in the callback
    /// from one in the caller's chunk, and the next stitched item overwrites it.
    /// One-shot does not either, so that a decoded message never has a shorter
    /// life than the caller thinks: the copy is what lets the input buffer be
    /// reused, overwritten or freed the moment decode() returns.
    ///
    /// This is the SCHEMA-BOUNDED entry point. A `maxlen` is a validity bound and
    /// stays the caller's, decided on `total` before this call; a field the
    /// schema leaves unbounded goes through _takeCapped instead.
    fn _take(self: *_Widths__Visitor, total: usize, offset: usize, chunk: []const u8) ?[]const u8 {
        return self.acc.take(self.alloc, total, offset, chunk, false) catch {
            self.inv = true;
            return null;
        };
    }

    pub fn sequenceBegin(self: *_Widths__Visitor, _: sofab.Id) void {
        if (self.sp < self.stack.len) {
            self.stack[self.sp] = self.cur;
            self.sp += 1;
        }
        self.cur = .dead;
    }

    pub fn sequenceEnd(self: *_Widths__Visitor) void {
        if (self.sp > 0) {
            self.sp -= 1;
            self.cur = self.stack[self.sp];
        } else {
            self.cur = .root;
        }
    }
};
